// Aircraft models manufactured by LET Aircraft Industries (case‑insensitive match)
MATCH (model:AircraftModel)-[:manufacturedBy]->(m:AircraftManufacturer)
WHERE toLower(m.name) CONTAINS "let" AND toLower(m.name) CONTAINS "aircraft"
RETURN DISTINCT model.name AS aircraftModelName
UNION
// All aircraft models involved in the 2021 Kemerovo parachute crash (no model‑name filter)
MATCH (acc:FlightAccident)-[:involves]->(model:AircraftModel)
WHERE (toLower(acc.name) CONTAINS "kemerovo" OR toLower(acc.description) CONTAINS "kemerovo")
  AND acc.date STARTS WITH "2021"
RETURN DISTINCT model.name AS aircraftModelName;
